-- =====================================================================
-- IETS and Water Meter Daily Log — Supabase database setup
-- Lam Soon Edible Oils Sdn. Bhd. (Telok Panglima Garang Factory)
--
-- Run this whole file once in Supabase: Dashboard -> SQL Editor -> New query
-- -> paste -> Run. It is safe to run again (it will not duplicate data).
-- =====================================================================

-- 1. Tables ------------------------------------------------------------

-- All log data: one row per record.
--   collection = 'logs'     (id = yyyy-mm-dd, one row per day)
--              = 'calib'    (calibration register, one row per instrument)
--              = 'settings' (id = 'limits', the discharge limits)
create table if not exists public.kv (
  collection  text        not null,
  id          text        not null,
  data        jsonb       not null,
  updated_at  timestamptz not null default now(),
  updated_by  text,
  primary key (collection, id)
);

-- People allowed to record readings. Everyone else can only view.
--   role 'owner'    = can also change the Limits tab
--   role 'recorder' = can save, edit and delete readings and calibration records
create table if not exists public.editors (
  email  text primary key,
  role   text not null default 'recorder' check (role in ('owner','recorder'))
);

-- 2. Permission helpers -----------------------------------------------

create or replace function public.is_editor() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.editors
                 where email = lower(coalesce(auth.jwt() ->> 'email','')));
$$;

create or replace function public.is_owner() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.editors
                 where email = lower(coalesce(auth.jwt() ->> 'email',''))
                   and role = 'owner');
$$;

grant execute on function public.is_editor() to anon, authenticated;
grant execute on function public.is_owner()  to anon, authenticated;

-- 3. Row Level Security -------------------------------------------------

alter table public.kv      enable row level security;
alter table public.editors enable row level security;

drop policy if exists kv_public_read   on public.kv;
drop policy if exists kv_editor_insert on public.kv;
drop policy if exists kv_editor_update on public.kv;
drop policy if exists kv_editor_delete on public.kv;
drop policy if exists editors_read_own on public.editors;

-- Anyone with the website link can READ the log.
create policy kv_public_read on public.kv
  for select to anon, authenticated using (true);

-- Only approved editors can WRITE. Limits ('settings') are owner-only.
create policy kv_editor_insert on public.kv
  for insert to authenticated
  with check (public.is_editor() and (collection <> 'settings' or public.is_owner()));

create policy kv_editor_update on public.kv
  for update to authenticated
  using      (public.is_editor() and (collection <> 'settings' or public.is_owner()))
  with check (public.is_editor() and (collection <> 'settings' or public.is_owner()));

create policy kv_editor_delete on public.kv
  for delete to authenticated
  using (public.is_editor() and (collection <> 'settings' or public.is_owner()));

-- A signed-in person can see only their own editor entry (the page uses this
-- to know whether to enable Save).
create policy editors_read_own on public.editors
  for select to authenticated
  using (email = lower(coalesce(auth.jwt() ->> 'email','')));

grant select                         on public.kv      to anon, authenticated;
grant insert, update, delete         on public.kv      to authenticated;
grant select                         on public.editors to authenticated;

-- 4. Live updates (other people's saves appear without reloading) -------

do $$
begin
  if not exists (select 1 from pg_publication_tables
                 where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'kv') then
    alter publication supabase_realtime add table public.kv;
  end if;
end $$;

-- 5. Approved editors (edit this list any time) ---------------------------

on conflict (email) do update set role = excluded.role;

-- 6. Existing data (copied from the Claude log on 21-10-2026) -------------

on conflict (collection, id) do nothing;

-- Check: should show logs 77, calib 5, settings 1
select collection, count(*) from public.kv group by collection order by collection;
